import {adviserContactHTML} from './narrative-advisers.js';
import {PRESIDENCIES,REGIONS,legalTargets,deploymentBlockReason} from './model.js';
import {operationsBlockReason} from './administration.js';
import {ORDER_OWNER} from './actions.js';

// Presentation only: all availability comes from the existing shared rules.
export function companyOperationsHTML(state,esc=String){
 const blocked=operationsBlockReason(state),orders=Object.keys(ORDER_OWNER).filter(id=>state.regions[ORDER_OWNER[id]].control==='indian'&&!state.regions[ORDER_OWNER[id]].orders[id]);
 const tradeReason=blocked||(state.laws.governorGeneral?'The Governor General has replaced the Director of Trade. Special Envoy is unavailable.':state.chinaOffice&&!orders.length?'The China office already exists and there are no closed Orders outside Company control.':'');
 return `<div class="operations-heading"><p class="eyebrow">COMPANY OPERATIONS</p><p>Choose an office or Army. Resolve physical commitments and checks on the table.</p></div><div class="operations-grid"><article class="operation-card"><h3>${state.laws.governorGeneral?'Governor General':'Director of Trade'}</h3>${adviserContactHTML(state,'director-of-trade',esc)}<p>${state.laws.governorGeneral?'Director of Trade replaced; regional Governor offices are removed. Use the Governor General controls below.':'Special Envoy: open a closed Indian Order outside Company control, or establish the China office.'}</p><button id="operations-envoy" ${tradeReason?'disabled':''} aria-describedby="operations-trade-reason">Special Envoy</button><p id="operations-trade-reason" class="small-note">${esc(tradeReason||'Choose a provisional intention; the successful effect may be revised before confirmation.')}</p></article>${PRESIDENCIES.map(army=>{const targets=legalTargets(state,army),reason=blocked||(!targets.length?deploymentBlockReason(state,army,army):'');return `<article class="operation-card"><h3>${REGIONS[army].name} Army</h3>${adviserContactHTML(state,'army:'+army,esc)}<p>Deploy from this Army, then choose a legal target.</p><button id="operations-deploy-${army}" ${reason?'disabled':''} aria-describedby="operations-${army}-reason">Deploy</button><p id="operations-${army}-reason" class="small-note">${esc(reason||`${targets.length} legal target${targets.length===1?'':'s'} · check available forces on the physical board.`)}</p></article>`;}).join('')}</div>`;
}
